Do the same for goAndWait's own throws (world.teleport ok:false, EVAL_TIMEOUT): wrap the per-site setup in try/catch. A USAGE error is rethrown. Any other error pushes `{shotId, siteId, stage: "setup", message}` for each of the site's shots and then `continue`s, so the remaining sites still run and the failures summary is still returned and printed. You can also attach the prewarm warning to that site's shot reports.

In shootSchedule (tools/film/lib/shoot.mjs:206), make prewarm non-fatal and isolate each site's setup:

```js
if (entry.prewarm) {
  try {
    const pw = await filmCallWith(page, { soft: true, timeoutMs: 300_000 }, "world.prewarm", entry.prewarm);
    if (pw && pw.ok === false) {
      if (pw.code === "NO_FILM" || pw.code === "NO_METHOD") {
        throw new FilmCliError(`__film.world.prewarm failed: ${pw.error?.message ?? pw.error}`, { exitCode: EXIT.USAGE, code: pw.code });
      }
      const missing = Object.entries(pw.missing ?? {}).filter(([, v]) => Array.isArray(v) && v.length).map(([k, v]) => `${k}: ${v.join(",")}`).join("; ");
      io.warn(`site ${entry.siteId}: prewarm incomplete (${pw.error?.message ?? pw.code}${missing ? `; missing ${missing}` : ""}) — shooting anyway, pop-in possible`);
      prewarmNote = { ok: false, missing: pw.missing ?? null, waitedMs: pw.waitedMs ?? null }; // attach to this site's shot reports/shoot-log
    }
  } catch (e) {
    if (e instanceof FilmCliError && e.exitCode === EXIT.USAGE) throw e;
    io.warn(`site ${entry.siteId}: prewarm failed (${e?.message ?? e}) — shooting anyway`);
  }
